const {spawn}=require('node:child_process'),{mkdtempSync,writeFileSync}=require('node:fs'),assert=require('node:assert/strict');
const baseline=process.argv[2],output=process.argv[3];if(!baseline||!output)throw Error('Usage: node tests/fixtures/baseline-crash.cjs BASELINE_SONG_SYSTEM OUTPUT_JSON');
function run(dir,channel,phase='',mode='',root=''){return new Promise((resolve,reject)=>{const p=spawn(process.execPath,['--import','tsx','tests/fixtures/crash-worker.mts'],{cwd:process.cwd(),env:{...process.env,LOCAL_ONLY:'1',SESSION_SECRET:'synthetic-only',DATA_DIR:dir,FIXTURE_CHANNEL:channel,FIXTURE_PHASE:phase,FIXTURE_MODE:mode,FIXTURE_ROOT:root}});let text='',err='';p.stdout.on('data',d=>{text+=d;if(phase&&text.includes('INTERPRETER_READY'))p.kill('SIGKILL')});p.stderr.on('data',d=>err+=d);p.on('error',reject);p.on('close',(code,signal)=>resolve({code,signal,text,err}))})}
(async()=>{const proof=[];for(const channel of ['site','telegram','instagram']){const dir=mkdtempSync('/tmp/legacy-crash-');const killed=await run(dir,channel,'interpreter','',baseline);assert.equal(killed.signal,'SIGKILL');const before=await run(dir,channel,'','',baseline);assert.match(before.text,channel==='site'?/INBOUND_IN_PROGRESS/:channel==='telegram'?/"needsReview":true/:/"status":200,"sends":0/);const after=await run(dir,channel,'','recover');assert.equal(after.code,0,after.text+after.err);assert.match(after.text,/ready_for_operator/);proof.push({channel,baseline:'6a3740653257777d7a4f9bd7278cdcf9cb4a9da3',killed:killed.signal,before:before.text.trim(),after:after.text.trim()})}writeFileSync(output,JSON.stringify(proof,null,2));console.log(JSON.stringify(proof))})().catch(e=>{console.error(e);process.exitCode=1});
